'use strict';
let engagementMonth=new Date().toISOString().slice(0,7),engagementDrafts={},cameraStream=null;
const isExternal=()=>state.account?.account_type==='external';
const gameButton=(label,action,id='',cls='secondary')=>`<button type="button" class="${cls}" data-game-action="${action}" data-game-id="${esc(id)}">${label}</button>`;
const myPoints=()=>state.points_summary?.find(p=>p.user===own())||{balance:0,earned:0};
const player=id=>state.public_players?.find(p=>p.id===id)||{alias:'Jugador Demo',avatar:null};
const gameForm=(action,content,extra='')=>`<form class="form inline" data-game-form="${action}" ${extra}>${content}</form>`;
function avatarSVG(a={},size=100){const colors={granate:'#92264d',azul:'#295da9',verde:'#267f64',violeta:'#7151ac'},skin={claro:'#f0c7a9',medio:'#c28c62',oscuro:'#754d36'},sport=a.sport||'Pádel',tier=a.tier||0;return `<svg class="sport-avatar" viewBox="0 0 120 130" width="${size}" height="${size}" role="img" aria-label="Avatar de ${esc(sport)}, equipación ${tier}"><circle cx="60" cy="60" r="58" fill="#edf0f8"/><path d="M30 115Q30 66 60 66T90 115" fill="${colors[a.color]||colors.granate}"/><circle cx="60" cy="43" r="23" fill="${skin[a.skin]||skin.medio}"/><path d="${a.hair==='largo'?'M35 65L34 35Q36 9 60 15T85 35L85 66 75 65 78 33Q58 23 42 35L45 65Z':a.hair==='recogido'?'M37 39Q30 18 49 14Q45 0 61 2Q77 0 72 15Q92 20 83 39Q62 23 37 39Z':'M37 39Q35 10 60 16T83 39Q60 21 37 39'}" fill="${({oscuro:'#263143',castano:'#78533d',rubio:'#d7b366'})[a.hair_color]||'#263143'}"/><circle cx="52" cy="43" r="2"/><circle cx="68" cy="43" r="2"/><path d="M52 54q8 8 16 0" stroke="#603c30" fill="none" stroke-width="2"/><text x="60" y="96" text-anchor="middle" fill="white" font-size="22">${sport==='Golf'?'⛳':sport==='Fútbol'?'⚽':sport==='Baloncesto'?'🏀':'🎾'}</text>${sport==='Golf'?`<path d="M92 112L105 55M100 56l13 2" stroke="${['#788390','#b3bac5','#c89735'][tier]}" stroke-width="${tier+3}" stroke-linecap="round"/>`:sport==='Pádel'||sport==='Tenis'?`<ellipse cx="100" cy="76" rx="10" ry="15" fill="none" stroke="${['#788390','#7684b5','#c89735'][tier]}" stroke-width="4"/><path d="M100 91v22" stroke="#526078" stroke-width="4"/>`:''}${tier?`<path d="M40 18L37 4l15 8L60 0l8 12 15-8-3 14" fill="${tier===2?'#e5b344':'#a9b7cb'}"/>`:''}</svg>`}
function progressMeter(label,value,detail){return `<div class="progress-meter"><div class="row"><b>${label}</b><strong>${Math.round(value)}%</strong></div><progress value="${Math.max(0,Math.min(100,value))}" max="100">${Math.round(value)}%</progress><small>${detail}</small></div>`}
function verifiedVisits(){return state.reservations.filter(r=>r.user===own()&&r.status==='Asistió').length+state.participation_invitations.filter(i=>i.user===own()&&i.attendance==='Asistió').length+(state.match_attendance||[]).filter(a=>a.user===own()).length}
function progressPanel(){let p=myPoints(),a=state.avatars?.[String(own())]||{},academic=state.my_academic,goal=academic?.sport_goal||4,month=day().slice(0,7),visits=state.reservations.filter(r=>r.user===own()&&r.status==='Asistió'&&r.date.startsWith(month)).length;return `<section class="game-hero"><div>${avatarSVG(a,145)}<p class="eyebrow">TU CAMPUS, TU RITMO</p><h1>Un pequeño paso.<br>Una nueva costumbre.</h1><p>La constancia cuenta. Tu avatar crece con acciones verificadas.</p><div class="actions"><button data-page="Ventajas">${p.balance} puntos disponibles →</button><button class="secondary" data-page="Avatar">Personalizar avatar</button></div></div><div class="progress-panel">${progressMeter('Mi objetivo deportivo',visits/goal*100,`${visits} asistencias a reservas este mes / objetivo personal de ${goal}`)}${academic?progressMeter('Mi referencia académica privada',academic.score*10,'Nota ficticia introducida por ti; no equivale a tu rendimiento real.'): '<h3>Tu equilibrio, sin competir con nadie</h3><p>Si quieres, añade una referencia académica ficticia solo para ti.</p>'}<button class="link" data-page="Mi progreso">Ajustar mis objetivos →</button><p class="compact muted">Consulta tus objetivos personales de estudios y deporte. Tu referencia académica es privada.</p></div></section>`}
const homeBeforeEngagement=home;
home=function(){if(isExternal())return `<section class="hero"><span class="eyebrow">ACCESO EXTERNO · INSTALACIONES</span><h1>Tu pista, a tu hora.</h1><p>Consulta las pistas disponibles, reserva tu hora y confirma tu asistencia.</p><button data-page="Reservas">Reservar instalación →</button></section><section class="card"><h2>Servicios de tu cuenta</h2><p>Tu cuenta permite reservar instalaciones y gestionar tus pagos y avisos. Las actividades universitarias están reservadas a estudiantes.</p></section>`;return progressPanel()+homeBeforeEngagement().replace(/<section class="hero">[\s\S]*?<\/section>/,'')};
function personalProgress(){let a=state.my_academic||{score:7,sport_goal:4};return progressPanel()+`<section class="card"><h2>Equilibrio académico y deportivo · opcional</h2><p>No hay conexión con el expediente universitario. Usa solo notas ficticias. Tus objetivos no cambian tus puntos ni tu prioridad de reserva.</p>${gameForm('academic_save',`${field('Nota ficticia de referencia (0–10)','score','number',a.score,'min="0" max="10" step="0.1" required')}${field('Objetivo de asistencias a reservas por mes','sport_goal','number',a.sport_goal,'min="1" max="20" required')}<label class="check wide"><input name="consent" type="checkbox" required>Quiero mostrar estas referencias ficticias solo en mi app.</label><button class="wide">Guardar referencias privadas</button>`)}</section>`}
function pointsView(){let p=myPoints();return `<div class="grid">${metric('Puntos disponibles',p.balance,'Pueden ser negativos tras una ausencia')}${metric('Progreso de equipación',p.earned,'Los canjes no quitan prendas ya desbloqueadas')}${metric('Asistencias registradas',verifiedVisits(),'Reservas, experiencias y partidas validadas')}</div><section class="card"><h2>Cómo sumas puntos</h2><div class="reward-rules"><span>😊 Reserva con asistencia <b>+12</b></span><span>🤝 Embajador aprobado <b>+30 una vez/deporte</b></span><span>🎪 Semana del Deporte validada <b>+20</b></span><span>↩ Cancelar a tiempo <b>+2, máximo dos/semana</b></span><span>😟 Sin check-in tras 15 min <b>−10, con revisión</b></span></div><p class="note">Reservar sin asistir, abrir la app o declarar un nivel alto no genera puntos. Todos los premios son ficticios y requieren acuerdos y presupuesto para un uso real.</p></section><div class="cards">${state.rewards.map(r=>`<section class="card reward-card"><span class="eyebrow">${esc(r.category)}</span><h2>${esc(r.name)}</h2><div class="price">${r.points} puntos</div><p>${esc(r.description)}</p><p>${r.stock} unidades demo · ${r.active?'Aprobada para el prototipo':'Pendiente de acuerdo institucional'}</p>${r.active?`<button data-game-action="reward_redeem" data-game-id="${r.id}" ${p.balance<r.points||!r.stock?'disabled':''}>Reservar ventaja ficticia</button>`:badge('No disponible aún','warn')}</section>`).join('')}</div><section class="card"><h2>Mis canjes</h2>${rows(state.redemptions,c=>`<div class="row"><div><b>${esc(c.name)}</b><p>${c.points} puntos · ${esc(c.status)}</p></div>${c.status==='Reservada'?gameButton('Cancelar y recuperar puntos','redemption_cancel',c.id):''}</div>`)}</section><section class="card"><h2>Historial de puntos</h2>${rows(state.points_ledger,l=>`<div class="row"><div><b>${esc(l.reason)}</b><p>${fmt(l.time)}</p></div>${badge((l.delta>0?'+':'')+l.delta,l.delta<0?'red':'')}</div>`)}</section>`}
function avatarView(){let a=state.avatars?.[String(own())]||{sport:'Golf',skin:'medio',color:'granate',tier:0},earned=myPoints().earned;return `<section class="card"><h2>Tu avatar deportivo</h2><div class="avatar-stage">${avatarSVG(a,220)}<div><h3>${['Equipación de inicio','Equipación de club','Equipación avanzada'][a.tier]}</h3><p>Las prendas son cosméticas, no acreditan tu habilidad. Sin marcas comerciales ni clasificación de personas.</p><div class="actions">${[0,60,150].map((n,i)=>badge(`${['Inicio','Club','Avanzada'][i]} · ${n} puntos ganados`,earned>=n?'':'warn')).join('')}</div></div></div>${gameForm('avatar_save',`${select('Deporte y accesorio','sport',sports,a.sport)}${select('Tono de piel','skin',[['claro','Claro'],['medio','Medio'],['oscuro','Oscuro']],a.skin)}${select('Estilo de pelo','hair',[['corto','Corto'],['largo','Largo'],['recogido','Recogido']],a.hair||'corto')}${select('Color de pelo','hair_color',[['oscuro','Oscuro'],['castano','Castaño'],['rubio','Rubio']],a.hair_color||'oscuro')}${select('Color de equipación','color',[['granate','Granate'],['azul','Azul'],['verde','Verde'],['violeta','Violeta']],a.color)}${select('Prenda desbloqueada','tier',[[0,'Inicio'],...(earned>=60?[[1,'Club']]:[]),...(earned>=150?[[2,'Avanzada']]:[])],a.tier)}<label class="check wide"><input name="public" type="checkbox" ${a.public?'checked':''}>Mostrar mi avatar y alias ficticio en competiciones de esta demo.</label><button class="wide">Guardar mi avatar</button>`)}</section>`}
function qrSVG(text){let qr=qrcodegen.QrCode.encodeText(text,qrcodegen.QrCode.Ecc.MEDIUM),paths=[];for(let y=0;y<qr.size;y++)for(let x=0;x<qr.size;x++)if(qr.getModule(x,y))paths.push(`M${x+4},${y+4}h1v1h-1z`);return `<svg class="location-qr" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${qr.size+8} ${qr.size+8}" role="img" aria-label="QR de instalación: ${esc(text)}"><rect width="100%" height="100%" fill="white"/><path d="${paths.join('')}" fill="#142034"/></svg>`}
function checkinForms(){let rr=state.reservations.filter(r=>r.user===own()&&r.status==='Confirmada');return `<section class="card"><h2>Check-in · QR de pista + clave de reserva</h2><p>Se abre 15 minutos antes y termina 15 minutos después del inicio. Sin confirmación, la reserva se cancela y la pista se libera. La clave es privada; el QR identifica la instalación y por sí solo no prueba presencia física.</p>${rows(rr,r=>`<article class="checkin-card"><h3>${esc(facility(r.facility)?.name)} · ${r.date} ${r.time}</h3><p>Tu clave: <code>${esc(r.access_code||'Reserva anterior a esta función: gestión valida la asistencia')}</code></p>${isExternal()?`<p>Tarifa ficticia por sesión: 12 €. ${state.payments.some(p=>p.entity===r.id&&p.status==='Pagado demo')?'Pago demo registrado.':'Completa el pago de prueba antes del check-in.'}</p>${!state.payments.some(p=>p.entity===r.id&&p.status==='Pagado demo')?gameForm('reservation_checkout',`<input type="hidden" name="id" value="${r.id}"><label class="check wide"><input name="confirm_demo" type="checkbox" required>Confirmar pago simulado de 12 € · Sin tarjeta ni cobro real.</label><button>Registrar pago de prueba</button>`):''}`:''}${r.access_code?gameForm('checkin',`<input type="hidden" name="id" value="${r.id}">${field('Contenido leído del QR de la pista','location','text','','required placeholder="UNAV-PISTA-'+r.facility+'"')}${field('Clave privada de la reserva','code','text','','required maxlength="6" autocomplete="off"')}<button type="button" class="secondary" data-scan-form="${r.id}">Escanear QR con cámara</button><button>Confirmar asistencia</button>`):''}</article>`,'No tienes reservas confirmadas pendientes de check-in.')}<video id="qr-camera" hidden playsinline muted></video><button id="stop-camera" hidden class="secondary">Cerrar cámara</button><p id="scan-status" role="status"></p><details><summary>Cómo probar el QR de la demo</summary><p>Los QR están disponibles para gestión en «Asistencia y sanciones». No son QR oficiales instalados en las pistas. Si tu navegador no reconoce QR con cámara, copia su contenido en el campo correspondiente. La clave se vuelve a comprobar en el servidor.</p></details></section>`}
function mySanctions(){return `<section class="card"><h2>Asistencia responsable y revisiones</h2><p>Una incidencia no significa mala intención. Puedes explicar un problema de acceso. La reducción temporal de reservas necesita revisión del servicio y no se aplica mientras haya una reclamación pendiente.</p>${rows(state.sanctions,p=>`<article class="card"><h3>😟 ${esc(p.reason)}</h3><p>${badge(p.status,'warn')} · ${p.penalty} puntos descontados${p.restriction?' · Límite semanal reducido hasta '+p.until.slice(0,10):''}</p>${p.resolution?`<p>${esc(p.resolution)}</p>`:''}${p.status!=='Revocada'&&(p.status!=='Confirmada'||!p.appeal)?gameForm('sanction_appeal',`<input type="hidden" name="id" value="${p.id}">${field('Explica lo ocurrido (solo datos ficticios)','reason','text',p.appeal||'','required maxlength="500"')}<button>Solicitar revisión</button>`):''}</article>`,'Sin incidencias de asistencia registradas.')}</section>`}
const bookingBeforeEngagement=booking;
booking=function(){let original=state.config;state.config={...original,...state.booking_policy};let content;try{content=bookingBeforeEngagement()}finally{state.config=original}return `<p class="note">${state.booking_policy.first_year?'🎓 Primer curso: disfruta de un día adicional de antelación. ':''}${state.booking_policy.restricted?'Límite temporal reducido tras revisión de gestión. ':''}Consulta aquí tus condiciones de reserva.</p>`+content+checkinForms()+mySanctions()};
function monthlyEvents(){let mine=state.reservations.filter(r=>r.user===own()).map(r=>({...r,title:facility(r.facility)?.name||'Reserva',kind:'Reserva',sport:facility(r.facility)?.sport}));if(!isExternal()){let interests=[...person(own()).practiced,...person(own()).interested];state.activities.filter(a=>interests.includes(a.sport)).forEach(a=>mine.push({...a,title:a.name,kind:'Actividad disponible'}));state.participation_sessions.forEach(p=>mine.push({...p,title:p.name,kind:'Experiencia'}));state.school_enrollments.filter(e=>e.status==='Inscrito').forEach(e=>{let g=state.schools.find(g=>g.id===e.school);if(g)mine.push({...e,title:g.name,kind:'Escuela'})});state.tournaments.filter(t=>interests.includes(t.sport)||state.tournament_entries.some(e=>e.tournament===t.id)).forEach(t=>mine.push({date:t.starts,time:'',title:t.name,kind:'Torneo',status:t.status}));state.sport_events.forEach(e=>mine.push({...e,title:e.name,kind:'Evento'}))}return mine.filter(e=>e.status!=='Cancelada')}
function monthView(){let [year,month]=engagementMonth.split('-').map(Number),first=new Date(year,month-1,1),offset=(first.getDay()+6)%7,total=new Date(year,month,0).getDate(),events=monthlyEvents();return `<section class="card"><div class="row"><h2>Tu calendario mensual</h2>${field('Mes','engagementMonth','month',engagementMonth)}</div><p>Reservas y compromisos, junto a eventos disponibles relacionados con tus intereses. «Disponible» no significa que estés inscrito. Consulta los detalles de cada evento antes de inscribirte.</p><div class="month-grid">${days.map(d=>`<b>${d.slice(0,3)}</b>`).join('')}${Array.from({length:offset},()=>'<div class="month-day blank"></div>').join('')}${Array.from({length:total},(_,i)=>{let date=`${year}-${String(month).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,ee=events.filter(e=>e.date===date);return `<div class="month-day ${date===day()?'today':''}"><b>${i+1}</b>${ee.map(e=>`<span class="calendar-event"><small>${esc(e.kind)} · ${esc(e.time)}</small>${esc(e.title)}</span>`).join('')}</div>`}).join('')}</div><h3>Lista accesible del mes</h3>${rows(events.filter(e=>e.date.startsWith(engagementMonth)).sort((a,b)=>a.date.localeCompare(b.date)),e=>`<p><b>${e.date} ${esc(e.time)}</b> · ${esc(e.kind)} · ${esc(e.title)}</p>`)}</section>`}
function schoolFits(g){let sc=state.schedule;if(!sc)return false;let a=mins(g.time),z=a+g.duration;return weeklyFree(sc,g.weekday,a,z)}
function schoolView(){return `<section class="hero"><span class="eyebrow">ESCUELAS DEPORTIVAS · CATÁLOGO FICTICIO</span><h1>Aprender con un grupo que encaja.</h1><p>Compara nivel, disponibilidad y precio antes de inscribirte. Tarifas y horarios de ejemplo; consulta las condiciones antes de confirmar.</p></section><div class="cards">${state.schools.map(g=>{let level=person(own()).sport_levels[g.sport]||'Principiante',fit=schoolFits(g),enrolled=state.school_enrollments.find(e=>e.school===g.id&&e.status==='Inscrito'),n=(state.school_occupancy||{})[g.id]||0;return `<section class="card"><span class="eyebrow">${esc(g.sport)} · ${esc(g.level)}</span><h2>${esc(g.name)}</h2><p>${days[g.weekday-1]} · ${g.time} · ${g.duration} min</p><p>Primera clase propuesta: <b>${esc(state.school_next_dates?.[g.id]||'Consulta disponibilidad')} · ${esc(g.time)}</b></p><p>Tu nivel: <b>${esc(level)}</b> · ${fit?'✓ Encaja en tu disponibilidad declarada':'Añade una franja compatible en Mi perfil'}</p><p>${n}/${g.capacity} plazas ocupadas · <b>${money(g.price)}</b> por primera clase de prueba</p><details><summary>Cómo llegar y qué necesitas</summary><p>${esc(g.location)}</p><p>${esc(g.directions)}</p><p>${esc(g.gear)}</p><p>${esc(g.description)}</p></details>${enrolled?`<p>${badge('Inscrito')} · Primera clase: ${enrolled.date} ${enrolled.time}</p>${gameButton('Cancelar inscripción y pago demo','school_cancel',enrolled.id)}`:level===g.level&&fit?gameForm('school_checkout',`<input type="hidden" name="id" value="${g.id}"><input type="hidden" name="expected_price" value="${g.price}"><output class="wide checkout-preview" aria-live="polite"></output><label class="check wide"><input name="confirm_demo" type="checkbox" required>Confirmar inscripción y pago de prueba de ${money(g.price)}. No hay cobro real.</label><button ${n>=g.capacity?'disabled':''}>Inscribirme con pago simulado</button>`):`<button class="secondary" data-page="Perfil deportivo">Ajustar nivel y disponibilidad</button>`}</section>`}).join('')}</div><p class="note">Inscribirse en una escuela no equivale a entrar en un equipo universitario: una selección o competición requiere evaluación y aprobación del servicio.</p>`}
function standings(t){let table=t.teams.map(name=>({name,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}));state.tournament_results.filter(r=>r.tournament===t.id).forEach(r=>{let h=table.find(x=>x.name===r.home),a=table.find(x=>x.name===r.away);if(!h||!a)return;h.p++;a.p++;h.gf+=r.home_score;h.ga+=r.away_score;a.gf+=r.away_score;a.ga+=r.home_score;if(r.home_score===r.away_score){h.d++;a.d++;h.pts++;a.pts++}else{let w=r.home_score>r.away_score?h:a,l=w===h?a:h;w.w++;w.pts+=3;l.l++}});return table.sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function tournamentCards(){return state.tournaments.map(t=>{let live=t.status==='En juego',rr=state.tournament_results.filter(r=>r.tournament===t.id),goals={};rr.flatMap(r=>r.scorers).forEach(g=>goals[g.user]=(goals[g.user]||0)+g.goals);return `<section class="card ${live?'tournament-live':''}"><div class="statusline">${badge(live?'● En juego':t.status,live?'':'warn')}${badge(t.sport)}</div><h2>${esc(t.name)}</h2><p>${t.starts} → ${t.ends}</p><p>${esc(t.description)}</p>${t.status==='Inscripción'&&!admin()?state.tournament_entries.some(e=>e.tournament===t.id)?badge('Ya inscrito'):gameForm('tournament_join',`<input type="hidden" name="id" value="${t.id}"><input type="hidden" name="expected_price" value="${t.price}"><output class="wide checkout-preview" aria-live="polite"></output><p class="wide">${money(t.price)} · inscripción ficticia</p><label class="check wide"><input type="checkbox" name="confirm_demo" required>Confirmar inscripción y pago simulado, sin cobro real.</label><button>Inscribirme en la demo</button>`):''}${live?`<h3>Clasificación validada</h3><div class="scroll"><table><thead><tr><th>Equipo</th><th>PJ</th><th>G</th><th>E</th><th>P</th><th>GF</th><th>GC</th><th>Puntos</th></tr></thead><tbody>${standings(t).map(r=>`<tr><td>${esc(r.name)}</td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}</td><td>${r.ga}</td><td>${r.pts}</td></tr>`).join('')}</tbody></table></div><h3>Resultados</h3>${rows(rr,r=>`<p>${esc(r.home)} <b>${r.home_score}–${r.away_score}</b> ${esc(r.away)}</p>`,'Todavía no hay resultados registrados; no se inventa una clasificación.')}<h3>Goleadores</h3>${rows(Object.entries(goals).sort((a,b)=>b[1]-a[1]),([id,n])=>`<div class="row"><span>${avatarSVG(player(Number(id)).avatar||{},45)} ${esc(player(Number(id)).alias)}</span><b>${n} goles</b></div>`,'Pendiente de actas con goleadores validados.')}`:''}</section>`}).join('')}
function tournamentsView(){return `<section class="hero"><span class="eyebrow">COMPETICIÓN EN EL CAMPUS</span><h1>Vive cada jornada.</h1><p>Consulta inscripciones, resultados y clasificaciones. La equipación del avatar refleja hábitos, no el nivel de juego.</p></section>`+tournamentCards()}
function paymentsView(){return `<section class="card"><h2>Mis pagos de prueba</h2><p>No se piden tarjetas ni datos bancarios. Estos justificantes son ficticios; no hay facturas ni ingresos reales.</p>${rows(state.payments,p=>`<div class="row"><div><b>${esc(p.kind)} · ${esc(p.sport)}</b><p>${p.reference} · ${fmt(p.time)} · ${esc(p.status)}</p></div><b>${money(p.amount)}</b></div>`)}</section>`}
function wrappedView(){let year=new Date().getFullYear(),visits=state.reservations.filter(r=>r.user===own()&&r.status==='Asistió'&&r.date.startsWith(String(year))),counts={},sportsCount={},partners={};visits.forEach(r=>{counts[r.facility]=(counts[r.facility]||0)+1;let s=facility(r.facility)?.sport||'Otro';sportsCount[s]=(sportsCount[s]||0)+1});state.matches.forEach(m=>{if(!m.date.startsWith(String(year))||!state.match_attendance.some(a=>a.match===m.id&&a.user===own()))return;sportsCount[m.sport]=(sportsCount[m.sport]||0)+1;(state.my_match_partners||[]).filter(x=>x.match===m.id).forEach(p=>partners[p.user]=(partners[p.user]||0)+1)});state.participation_invitations.filter(i=>i.user===own()&&i.attendance==='Asistió').forEach(i=>{let p=state.participation_sessions.find(p=>p.id===i.session&&p.date.startsWith(String(year)));if(p){counts[p.facility]=(counts[p.facility]||0)+1;sportsCount[p.sport]=(sportsCount[p.sport]||0)+1}});state.tournament_entries.filter(e=>e.attended_at&&e.attended_at.startsWith(String(year))).forEach(e=>{let t=state.tournaments.find(t=>t.id===e.tournament);if(t?.facility){counts[t.facility]=(counts[t.facility]||0)+1;sportsCount[t.sport]=(sportsCount[t.sport]||0)+1}});let totalVisits=Object.values(counts).reduce((n,x)=>n+x,0);
let fav=Object.entries(sportsCount).sort((a,b)=>b[1]-a[1])[0],friend=Object.entries(partners).sort((a,b)=>b[1]-a[1])[0];return `<section class="game-hero"><div>${avatarSVG(state.avatars?.[String(own())]||{},160)}<span class="eyebrow">MI AÑO DEPORTIVO · ${year}</span><h1>Tu historia sigue sumando.</h1><p>Resumen hasta hoy. Refleja tus asistencias confirmadas.</p></div><div class="progress-panel"><h2>${totalVisits} registros de presencia en instalaciones</h2><p>Deporte con más presencias registradas: <b>${fav?esc(fav[0]):'Aún por descubrir'}</b></p><p>Compañero más habitual en partidas verificadas: <b>${friend?esc(player(Number(friend[0])).alias)+' · '+friend[1]+' partidas':'Pendiente de partidas con asistencia validada'}</b></p></div></section><section class="card"><h2>Tu mapa de visitas</h2><p>Explora tus visitas por instalación.</p><div class="facility-map">${state.facilities.map(f=>`<article class="map-facility ${counts[f.id]?'visited':''}"><span>${counts[f.id]?avatarSVG(state.avatars?.[String(own())]||{},70):'📍'}</span><h3>${esc(f.name)}</h3><b>${counts[f.id]||0} visitas verificadas</b></article>`).join('')}</div><p class="note">Cuenta reservas, experiencias y torneos con asistencia validada e instalación identificada. Son registros de presencia, no días distintos. Las cancelaciones, ausencias y aperturas de pantalla no cuentan. No se registra tu ubicación GPS.</p></section>`}
function wellbeingView(){let w=state.my_wellness||{goal:'Empezar con regularidad',minutes:20};return `<section class="hero"><span class="eyebrow">TU BIENESTAR · OPCIONAL Y PRIVADO</span><h1>Organiza hábitos.<br>Escucha tus necesidades.</h1><p>Organiza tus hábitos y sigue tus objetivos personales. Tus referencias personales y vídeos son privados.</p></section><section class="card"><h2>Mi diario privado de demostración</h2><p>Los valores se guardan solo en tu espacio del prototipo. No hay conexión sanitaria ni cálculo de calorías, diagnóstico o dieta personalizada.</p>${gameForm('wellness_save',`${select('Objetivo de organización','goal',['Empezar con regularidad','Movilidad y descanso','Organizar mi semana'],w.goal)}${field('Minutos que quiero reservar a mi rutina','minutes','number',w.minutes,'min="5" max="60" required')}${field('Peso ficticio (opcional, kg)','weight','number',w.weight||'','min="30" max="250" step="0.1"')}${field('Estatura ficticia (opcional, cm)','height','number',w.height||'','min="100" max="230"')}<label class="wide">Mi registro de comidas ficticio<textarea name="meal_note" maxlength="300">${esc(w.meal_note||'')}</textarea></label><label class="wide">Mi rutina y preferencias ficticias<textarea name="training_note" maxlength="500">${esc(w.training_note||'')}</textarea></label><label class="check wide"><input name="consent" type="checkbox" required>Usaré solo datos ficticios y quiero guardar este diario privado.</label><button class="wide">Guardar diario privado</button>`)}<label>Foto de un plato ficticio · previsualización local<input id="meal-photo" type="file" accept="image/*"></label><img id="meal-preview" hidden alt="Foto de plato seleccionada, solo previsualización local"><p class="muted">La foto no se guarda en el servidor ni se analiza. No se infieren nutrientes o salud a partir de ella.</p>${gameButton('Borrar mis referencias privadas de bienestar y estudios','wellness_clear','','danger')}</section><section class="card"><h2>Mi borrador de organización</h2><p>Objetivo elegido: <b>${esc(w.goal)}</b>. Puedes reservar en tu agenda ${w.minutes} minutos para una actividad que ya conozcas y te resulte cómoda, y revisar después si esa organización te encaja. Esto no prescribe una rutina física ni una dieta.</p><button data-page="Calendario mensual">Ver mis compromisos del mes</button>${studentAI('wellness','Ayudarme a organizar hábitos')}</section><section class="card"><h2>Estudio de técnica · vídeo privado</h2><p>Selecciona un clip corto de técnica de una persona ficticia o material autorizado. Se previsualiza localmente. Si activas IA externa, se envían únicamente tres fotogramas reducidos para comentarios orientativos; no se certifica el nivel ni se detectan lesiones.</p><label>Deporte<select id="technique-sport">${sports.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Vídeo local (máximo 30 MB)<input id="technique-video" type="file" accept="video/*"></label><video id="technique-preview" controls playsinline hidden></video><p id="video-local-status" role="status"></p>${studentAI('technique','Revisar tres fotogramas con IA')}<h3>Tutorial a tu ritmo</h3><p>Elige un deporte y pide un borrador de explicación. No se genera un vídeo nuevo: la ayuda devuelve texto para revisión. Para correcciones personales, acude a un técnico del servicio.</p>${studentAI('tutorial','Preparar tutorial de técnica')}</section>`}
function studentAI(kind,label){return `<div class="student-ai"><p class="eyebrow">AYUDA OPCIONAL · ${state.ai_available?'IA EXTERNA DISPONIBLE':'IA EXTERNA SIN CONFIGURAR'}</p>${state.ai_available?`<label class="check"><input type="checkbox" data-student-ai-consent="${kind}">${kind==='technique'?'Autorizo enviar tres fotogramas del clip a OpenAI para esta consulta.':'Autorizo enviar el objetivo y los minutos elegidos, o el deporte, a OpenAI para esta consulta. No se envían peso, estatura, notas ni fotos de comida.'}</label><button type="button" data-student-ai="${kind}">${label}</button>`:'<p>Esta ayuda necesita que se configure la conexión de IA del servidor. No se simula un análisis inexistente. Puedes utilizar el resto del diario y las reservas sin IA.</p>'}<textarea data-student-ai-output="${kind}" aria-label="Borrador editable de ${kind}" rows="6" placeholder="Borrador para revisar, no diagnóstico ni evaluación certificada">${esc(engagementDrafts['ai:'+own()+':'+kind]||'')}</textarea><p data-student-ai-status="${kind}" role="status"></p></div>`}
function crmRewards(){return `<section class="hero"><span class="eyebrow">HÁBITOS QUE CONSTRUYEN COMUNIDAD</span><h1>Reconocer la constancia.</h1><p>Reconoce la asistencia y los buenos hábitos. Gestiona puntos, existencias y entrega de ventajas desde un mismo lugar.</p></section><section class="card"><h2>Saldos y canjes</h2><div class="scroll"><table><thead><tr><th>Usuario ficticio</th><th>Puntos disponibles</th><th>Progreso ganado</th></tr></thead><tbody>${state.points_summary.filter(p=>person(p.user).account_type!=='external').map(p=>`<tr><td>${esc(person(p.user).name)}</td><td>${p.balance}</td><td>${p.earned}</td></tr>`).join('')}</tbody></table></div><button data-page="Comunicaciones">Contactar con beneficiarios →</button></section><section class="card"><h2>Catálogo y acuerdos</h2><p>Activar solo confirma una ventaja ficticia para la demo. Antes de un uso real hay que acordar presupuesto, proveedor, criterios, cupos y responsables. No existe una charla confirmada de Rafa Nadal ni un descuento real de matrícula.</p>${rows(state.rewards,r=>`<div class="row"><div><b>${esc(r.name)}</b><p>${r.points} puntos · ${r.stock} unidades · ${r.active?'Activa en demo':'Pendiente de autorización'}</p></div>${gameForm('reward_toggle',`<input type="hidden" name="id" value="${r.id}"><label class="check wide"><input type="checkbox" name="reviewed" required>He revisado acuerdo ficticio, coste y existencias.</label><button>${r.active?'Pausar ventaja':'Activar en demo'}</button>`)}</div>`)}</section><section class="card"><h2>Canjes pendientes y entregas</h2>${rows(state.redemptions,c=>`<div class="row"><div><b>${esc(person(c.user).name)} · ${esc(c.name)}</b><p>${esc(c.status)} · ${c.points} puntos</p></div><div class="actions">${c.status==='Reservada'?gameButton('Registrar entrega ficticia','redemption_fulfill',c.id)+gameButton('Cancelar y devolver puntos','redemption_cancel',c.id):''}</div></div>`)}</section><section class="card"><h2>Validar Semana del Deporte</h2><p>La asistencia la confirma gestión cuando ha comenzado el evento, una vez por persona. No basta con pulsar «me interesa».</p>${rows(state.sport_events,e=>`<h3>${esc(e.name)} · ${e.date} ${e.time}</h3>${gameForm('event_attend',`<input type="hidden" name="id" value="${e.id}">${select('Estudiante presente','user',state.users.filter(u=>u.account_type==='student').map(u=>[u.id,u.name]))}<button>Validar asistencia y puntos</button>`)}`)}<h3>Publicar un evento ficticio</h3>${gameForm('event_create',`${field('Nombre','name','text','','required maxlength="100"')}${field('Fecha','date','date',day(1),'required')}${field('Hora','time','time','12:00','required')}${field('Lugar','location','text','Recepción del polideportivo','required')}<button>Crear evento de demo</button>`)}</section>`}
function crmAttendance(){return `<section class="card"><h2>QR identificativos de las pistas</h2><p>Consulta el identificador QR de cada pista para el registro de asistencia. La asistencia requiere el QR de la pista y la clave de la reserva.</p><div class="cards">${state.facilities.map(f=>`<article><h3>${esc(f.name)}</h3>${qrSVG('UNAV-PISTA-'+f.id)}<code>UNAV-PISTA-${f.id}</code></article>`).join('')}</div></section><section class="card"><h2>Revisión de ausencias y sanciones</h2><p>Las reservas con check-in obligatorio se liberan tras 15 minutos sin confirmar. La reducción de una reserva semanal durante siete días requiere revisión de gestión. Una reclamación pendiente no aplica esa reducción.</p>${rows(state.sanctions,p=>`<article class="card"><h3>${esc(person(p.user).name)} · ${esc(p.status)}</h3><p>${esc(p.reason)} · −${p.penalty} puntos</p>${p.appeal?`<p>Solicitud del usuario: ${esc(p.appeal)}</p>`:''}${!['Revocada','Confirmada'].includes(p.status)?gameForm('sanction_resolve',`<input type="hidden" name="id" value="${p.id}">${select('Decisión','decision',[['revoke','Revertir la penalización de puntos'],['confirm','Confirmar la incidencia']])}${field('Motivo de la resolución','reason','text','','required maxlength="500"')}<label class="check wide"><input name="restriction" type="checkbox">Si confirmo, reducir el límite semanal en una reserva hasta el fin del periodo.</label><button>Registrar decisión y avisar en la app</button>`):`<p>${esc(p.resolution||'')}</p>`}</article>`)}</section><section class="card"><h2>Partidas: validar presencia para valorar nivel</h2><p>Solo se abre una valoración entre compañeros que tienen asistencia validada. Nunca se cambia automáticamente el nivel autodeclarado.</p>${rows(state.matches,m=>`<h3>${esc(m.name)} · ${m.date} ${m.time}</h3>${m.participants.map(id=>gameForm('match_attendance',`<input type="hidden" name="id" value="${m.id}"><input type="hidden" name="user" value="${id}"><p>${esc(person(id).name)}</p><button>Confirmar asistencia de este jugador</button>`)).join('')}`)}</section>`}
function crmSchools(){return `<section class="card"><h2>Participación en escuelas</h2><p>Inscritos únicos y pagos de prueba; no equivalen a asistencia. Una inscripción confirma la primera clase de demostración, no una temporada completa.</p><div class="cards">${state.schools.map(g=>{let ee=state.school_enrollments.filter(e=>e.school===g.id&&e.status==='Inscrito');return `<article class="card"><h3>${esc(g.name)}</h3>${metric('Plazas ocupadas',ee.length+'/'+g.capacity,days[g.weekday-1]+' '+g.time)}${rows(ee,e=>`<p>${esc(person(e.user).name)} · ${e.date} ${e.time}</p>`)}<details><summary>Editar información y oferta de demo</summary>${gameForm('school_update',`<input type="hidden" name="id" value="${g.id}">${select('Nivel de entrada','level',levels,g.level)}${select('Día semanal','weekday',days.map((d,i)=>[i+1,d]),g.weekday)}${field('Hora','time','time',g.time,'required')}${field('Plazas','capacity','number',g.capacity,'min="1" max="100" required')}${field('Precio por primera clase (€)','price','number',g.price,'min="0" max="1000" step="0.01" required')}${field('Punto de encuentro','location','text',g.location,'required maxlength="200"')}${field('Cómo llegar','directions','text',g.directions,'required maxlength="300"')}${field('Equipación','gear','text',g.gear,'required maxlength="300"')}<button>Guardar oferta ficticia</button>`)}</details></article>`}).join('')}</div></section>`}
function crmFinance(){let paid=state.payments.filter(p=>p.status==='Pagado demo'),refund=state.payments.filter(p=>p.status==='Reembolsado demo');return `<section class="hero"><span class="eyebrow">INGRESOS POR DEPORTE · SOLO PRUEBA</span><h1>De la inscripción al dato económico.</h1><p>Cada pago simulado enlaza persona, deporte y servicio. No se han cobrado fondos ni conectado una pasarela bancaria.</p></section><div class="grid">${metric('Pagos demo vigentes',money(paid.reduce((n,p)=>n+p.amount,0)),'Excluye reembolsados')}${metric('Reembolsos demo',money(refund.reduce((n,p)=>n+p.amount,0)))}${metric('Operaciones',state.payments.length)}</div><section class="card"><h2>Desglose por deporte</h2><table><thead><tr><th>Deporte</th><th>Operaciones vigentes</th><th>Total demo</th></tr></thead><tbody>${sports.map(s=>{let pp=paid.filter(p=>p.sport===s);return `<tr><td>${s}</td><td>${pp.length}</td><td>${money(pp.reduce((n,p)=>n+p.amount,0))}</td></tr>`}).join('')}</tbody></table><p class="note">Estos totales no son beneficios ni contabilidad conciliada: no incorporan costes, impuestos o fondos reales.</p></section><section class="card"><h2>Libro de operaciones ficticias</h2><div class="scroll"><table><thead><tr><th>Referencia</th><th>Persona</th><th>Concepto</th><th>Deporte</th><th>Importe</th><th>Estado</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td>${esc(p.reference)}</td><td>${esc(person(p.user).name)}</td><td>${esc(p.kind)}</td><td>${esc(p.sport)}</td><td>${money(p.amount)}</td><td>${esc(p.status)}</td></tr>`).join('')}</tbody></table></div></section>`}
function crmCompetitions(){return `<section class="card"><h2>Publicar resultados validados</h2><p>Datos ficticios. Cada cruce admite un acta en este piloto. Los goleadores deben estar inscritos; no se atribuyen goles inventados automáticamente.</p>${state.tournaments.filter(t=>t.status==='En juego').map(t=>`<h3>${esc(t.name)}</h3>${gameForm('tournament_result',`<input type="hidden" name="id" value="${t.id}">${select('Equipo local','home',t.teams,t.teams[0])}${select('Equipo visitante','away',t.teams,t.teams[1])}${field('Goles local','home_score','number',0,'min="0" max="99" required')}${field('Goles visitante','away_score','number',0,'min="0" max="99" required')}${select('Goleador ficticio (opcional)','scorer',[['','No registrar goleador'],...state.public_players.map(p=>[p.id,p.alias])])}${field('Goles del jugador','goals','number',0,'min="0" max="99"')}<button>Publicar resultado validado</button>`)}`).join('')}</section>`+tournamentCards()}
function peerView(){return `<section class="card"><h2>Nivel: tu percepción y la experiencia compartida</h2><p>Las valoraciones son orientativas, no una certificación ni una puntuación pública. Se abren una hora después del final de la partida y solo entre asistentes validados.</p>${rows(state.review_opportunities,r=>gameForm('level_review',`<input type="hidden" name="id" value="${r.match}"><input type="hidden" name="user" value="${r.user}"><h3 class="wide">${esc(r.name)} · ${esc(player(r.user).alias)}</h3>${select('Nivel observado en '+r.sport,'level',levels,'Intermedio')}<button>Enviar valoración respetuosa</button>`),'Aún no hay partidas elegibles para valorar.')}<h3>Mis valoraciones recibidas</h3>${rows(state.my_level_feedback,r=>`<p><b>${esc(r.sport)}</b> · ${r.reviewers} compañeros distintos · ${r.distribution?Object.entries(r.distribution).map(([l,n])=>esc(l)+': '+n).join(' · '):'Detalle reservado hasta tres compañeros distintos para evitar identificar a una persona.'}</p>`)}</section>`}
const composeBeforePoints=composeCampaign;
composeCampaign=function(){let d=editorValues();return composeBeforePoints().replace('<button class="wide">Guardar borrador</button>',`${field('Puntos disponibles mínimos (0 = sin filtro)','minimum_points','number',d.minimum_points||0,'min="0" max="100000" required')}${select('Ventaja ya reservada o entregada','reward',[['','No filtrar por ventaja'],...state.rewards.map(r=>[r.id,r.name])],d.reward||'')}<p class="note wide">Combina los filtros para seleccionar destinatarios. Las ventajas se identifican por canjes reservados o entregados y se respetan las preferencias del buzón.</p><button class="wide">Guardar borrador</button>`)};
const campaignBeforePoints=campaignCard;
campaignCard=function(c){return campaignBeforePoints(c).replace('<div class="message-preview">',`<p class="muted">Puntos mínimos: ${c.segment.minimum_points||0} · Ventaja: ${esc(state.rewards.find(r=>r.id===c.segment.reward)?.name||'Sin filtro')}</p><div class="message-preview">`)};
const customerBeforeGame=customer;
customer=function(){let p=state.points_summary.find(x=>x.user===selectedUser)||{balance:0};return `<section class="card"><h2>Hábitos, ventajas y pagos demo</h2><p>${p.balance} puntos disponibles · ${state.redemptions.filter(r=>r.user===selectedUser&&r.status!=='Cancelada').length} canjes · ${money(state.payments.filter(p=>p.user===selectedUser&&p.status==='Pagado demo').reduce((n,p)=>n+p.amount,0))} en pagos de prueba vigentes.</p><p class="muted">Este perfil reúne actividad deportiva, ventajas y pagos.</p></section>`+customerBeforeGame()};
const renderBeforeGame=render;
render=function(){
 document.querySelectorAll('[data-local-url]').forEach(el=>{try{URL.revokeObjectURL(el.dataset.localUrl)}catch(_){}});
 if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}
 if(state&&session&&!admin()&&isExternal()){firstAccess.add(own());if(!['Inicio','Reservas','Incidencias','Buzón','Calendario mensual','Mis pagos'].includes(page))page='Inicio'}
 renderBeforeGame();if(!state||!session)return;
 let extra=admin()?['Puntos y ventajas','Asistencia y sanciones','Escuelas','Competiciones','Ingresos']:isExternal()?['Calendario mensual','Mis pagos']:['Mi progreso','Ventajas','Avatar','Calendario mensual','Escuelas deportivas','Ligas y torneos','Mis pagos','Mi año deportivo','Técnica y bienestar'];
 if(!admin()&&isExternal())$('nav').querySelectorAll('button[data-page]').forEach(b=>{if(!['Inicio','Reservas','Incidencias','Buzón'].includes(b.dataset.page))b.remove()});
 extra.forEach(n=>{let b=document.createElement('button');b.textContent=n;b.dataset.page=n;b.className=page===n?'active':'';b.onclick=()=>{page=n;render()};$('nav').insertBefore(b,$('nav').lastElementChild)});
 let views=admin()?{'Puntos y ventajas':crmRewards,'Asistencia y sanciones':crmAttendance,'Escuelas':crmSchools,'Competiciones':crmCompetitions,'Ingresos':crmFinance}:{'Mi progreso':personalProgress,'Ventajas':pointsView,'Avatar':avatarView,'Calendario mensual':monthView,'Escuelas deportivas':schoolView,'Ligas y torneos':tournamentsView,'Mis pagos':paymentsView,'Mi año deportivo':wrappedView,'Técnica y bienestar':wellbeingView};
 if(views[page]){$('main').innerHTML=heading()+views[page]();bind()}
 if(!admin()&&!isExternal()&&page==='Perfil deportivo')$('main').insertAdjacentHTML('afterbegin','<section class="card"><h2>Tu identidad deportiva</h2><p>Puedes crear tu avatar al configurar el perfil y cambiarlo cuando quieras.</p><button data-page="Avatar">Crear o editar mi avatar →</button></section>');
 if(!admin()&&!isExternal()&&['Partidas','Perfil deportivo'].includes(page))$('main').insertAdjacentHTML('beforeend',peerView());
 if(admin()&&page==='Reservas')$('main').insertAdjacentHTML('afterbegin','<section class="card"><h2>Asistencia y reglas piloto</h2><p>Las nuevas reservas requieren check-in. Tras 15 minutos sin confirmar se liberan. Los QR y las revisiones están en «Asistencia y sanciones».</p><button data-page="Asistencia y sanciones">Ver QR y revisar incidencias</button></section>');
 if(!admin()&&isExternal()&&page==='Buzón')$('main').innerHTML=heading()+`<section class="card"><h2>Avisos de tu servicio</h2>${rows(state.deliveries,d=>`<article><h3>${esc(d.title)}</h3><p>${esc(d.body)}</p></article>`)}</section>`;
 bind();personalBind();participationBind();communicationBind();strategyBind();engagementBind();
 // Keep partially edited forms stable if another account changes the shared revision.
 document.querySelectorAll('[data-game-form]').forEach(f=>{let key=page+':'+f.dataset.gameForm+':'+(f.elements.id?.value||f.elements.user?.value||'');let d=engagementDrafts[key];if(d)Object.entries(d).forEach(([k,v])=>{let el=f.elements[k];if(el&&el.type!=='file'&&k!=='expected_price'){if(el.type==='checkbox')el.checked=k==='confirm_demo'&&d.expected_price!==undefined&&Number(d.expected_price)!==Number(f.elements.expected_price?.value)?false:v===true;else el.value=v}});f.oninput=()=>{engagementDrafts[key]=Object.fromEntries(new FormData(f));['consent','public','confirm_demo','restriction','reviewed'].forEach(k=>{if(f.elements[k])engagementDrafts[key][k]=f.elements[k].checked})}});
 refreshCheckoutPreviews();
};
async function gameSend(action,data={}){if(busy)return;busy=true;try{await api('action',{action,...data});engagementDrafts={};await refresh(true);toast(action==='checkin'?(isExternal()?'😊 ¡Muy bien! Asistencia confirmada.':'😊 ¡Muy bien! Estás sumando puntos: +12 por tu asistencia confirmada.'):action.includes('checkout')||action==='tournament_join'?'Operación de prueba guardada: no se ha cobrado dinero real.':'Cambios guardados.')}catch(e){toast(e.message,true)}finally{busy=false}}
function engagementBind(){
 document.querySelectorAll('[data-game-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;let v=Object.fromEntries(new FormData(f));['consent','public','confirm_demo','restriction','reviewed'].forEach(k=>{if(f.elements[k])v[k]=f.elements[k].checked});if(f.dataset.gameForm==='tournament_result'){v.scorers=v.scorer?[{user:Number(v.scorer),goals:Number(v.goals)}]:[];delete v.scorer;delete v.goals}gameSend(f.dataset.gameForm,v)});
 document.querySelectorAll('[data-game-action]').forEach(b=>b.onclick=()=>gameSend(b.dataset.gameAction,{id:b.dataset.gameId}));
 let month=document.querySelector('[name="engagementMonth"]');if(month)month.onchange=()=>{if(/^\d{4}-\d{2}$/.test(month.value)){engagementMonth=month.value;render()}};
 document.querySelectorAll('[data-scan-form]').forEach(b=>b.onclick=()=>startQRScan(b.dataset.scanForm));let stop=$('stop-camera');if(stop)stop.onclick=stopQRScan;
 let photo=$('meal-photo');if(photo)photo.onchange=()=>{let file=photo.files[0];if(!file)return;if(file.size>5000000)return toast('Utiliza una imagen de menos de 5 MB.',true);let img=$('meal-preview');if(img.dataset.localUrl)URL.revokeObjectURL(img.dataset.localUrl);img.dataset.localUrl=URL.createObjectURL(file);img.src=img.dataset.localUrl;img.hidden=false};
 let video=$('technique-video');if(video)video.onchange=()=>{let file=video.files[0],preview=$('technique-preview');if(!file)return;if(file.size>30000000)return toast('El vídeo local debe ocupar menos de 30 MB.',true);if(preview.dataset.localUrl)URL.revokeObjectURL(preview.dataset.localUrl);preview.dataset.localUrl=URL.createObjectURL(file);preview.src=preview.dataset.localUrl;preview.hidden=false;$('video-local-status').textContent='Vídeo local cargado. No se ha enviado al servidor ni analizado.'};
 document.querySelectorAll('[data-student-ai]').forEach(b=>b.onclick=()=>studentAICall(b));
}
function stopQRScan(){if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;if($('qr-camera'))$('qr-camera').hidden=true;if($('stop-camera'))$('stop-camera').hidden=true}
async function startQRScan(id){
 let status=$('scan-status');if(!navigator.mediaDevices?.getUserMedia){status.textContent='La cámara no está disponible en este contexto. Puedes introducir el contenido del QR manualmente.';return}
 try{
  stopQRScan();cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});let video=$('qr-camera');video.srcObject=cameraStream;video.hidden=false;$('stop-camera').hidden=false;await video.play();
  let detector='BarcodeDetector' in window?new BarcodeDetector({formats:['qr_code']}):null,canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});status.textContent='Busca el QR de la instalación. Lectura local; la cámara no graba ni envía imágenes.';
  const scan=async()=>{
   if(!cameraStream||!video.isConnected)return;
   try{
    let raw='';if(detector){let codes=await detector.detect(video);raw=codes[0]?.rawValue||''}else if(video.videoWidth){let ratio=Math.min(1,640/video.videoWidth);canvas.width=Math.floor(video.videoWidth*ratio);canvas.height=Math.floor(video.videoHeight*ratio);ctx.drawImage(video,0,0,canvas.width,canvas.height);let image=ctx.getImageData(0,0,canvas.width,canvas.height);raw=jsQR(image.data,image.width,image.height)?.data||''}
    if(raw){let form=[...document.querySelectorAll('[data-game-form="checkin"]')].find(f=>f.elements.id.value===id);if(form){form.elements.location.value=raw;form.dispatchEvent(new Event('input'));status.textContent='QR leído. Introduce ahora tu clave privada y confirma.'}stopQRScan();return}
   }catch(_){status.textContent='Ajusta la cámara o introduce el contenido del QR.'}
   if(cameraStream)setTimeout(scan,400)
  };scan()
 }catch(_){stopQRScan();status.textContent='No se ha podido usar la cámara. Puedes introducir el contenido del QR manualmente.'}
}
async function videoFrames(){let video=$('technique-preview');if(!video?.src||!Number.isFinite(video.duration))throw Error('Carga y espera a que se prepare un vídeo local antes de continuar.');if(video.duration>120)throw Error('Selecciona un clip de hasta dos minutos.');let canvas=document.createElement('canvas'),ratio=Math.min(1,512/video.videoWidth);canvas.width=Math.round(video.videoWidth*ratio);canvas.height=Math.round(video.videoHeight*ratio);if(!canvas.width||!canvas.height)throw Error('El navegador no puede leer este formato de vídeo.');let frames=[];for(let part of [.2,.5,.8]){let target=Math.min(video.duration*part,Math.max(0,video.duration-.05));await new Promise((resolve,reject)=>{let timer=setTimeout(()=>{video.removeEventListener('seeked',onseek);reject(Error('No se pudo leer un fotograma del vídeo.'))},5000);function onseek(){clearTimeout(timer);resolve()}video.addEventListener('seeked',onseek,{once:true});video.currentTime=target});canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);frames.push(canvas.toDataURL('image/jpeg',.65))}return frames}
async function studentAICall(button){if(busy)return;let kind=button.dataset.studentAi,consent=document.querySelector(`[data-student-ai-consent="${kind}"]`),status=document.querySelector(`[data-student-ai-status="${kind}"]`);if(!consent.checked){status.textContent='Activa el envío opcional al servicio externo para esta consulta.';return}button.disabled=true;busy=true;status.textContent='Preparando una consulta de revisión…';try{let payload={kind,external_consent:true,sport:$('technique-sport')?.value||'Golf'};if(kind==='wellness'){payload.goal=state.my_wellness?.goal||'Organizar mi semana';payload.minutes=state.my_wellness?.minutes||20}if(kind==='technique')payload.frames=await videoFrames();let result=await api('assistant',payload);engagementDrafts['ai:'+own()+':'+kind]=result.draft;document.querySelector(`[data-student-ai-output="${kind}"]`).value=result.draft;status.textContent='Borrador orientativo de IA. No valida tu nivel ni sustituye orientación de un profesional.'}catch(e){status.textContent=e.message}finally{button.disabled=false;busy=false}}
const competitionsBeforeAttendance=crmCompetitions;
crmCompetitions=function(){return competitionsBeforeAttendance()+`<section class="card"><h2>Validar participación en competiciones</h2><p>Concede 20 puntos una vez por torneo, solo a inscritos y cuando el torneo ha comenzado.</p>${rows(state.tournament_entries,e=>{let t=state.tournaments.find(t=>t.id===e.tournament);return t?`<div class="row"><div><b>${esc(person(e.user).name)}</b><p>${esc(t.name)} · ${e.attended_at?'Presencia validada':'Pendiente'}</p></div>${!e.attended_at?gameForm('tournament_attend',`<input type="hidden" name="id" value="${t.id}"><input type="hidden" name="user" value="${e.user}"><button>Validar presencia</button>`):''}</div>`:''})}</section>`};
const schoolBeforeDiscounts=schoolView;
schoolView=function(){let html=schoolBeforeDiscounts(),eligible=state.redemptions.filter(r=>r.status==='Reservada'&&r.reward==='padel');if(eligible.length)state.schools.filter(g=>g.sport==='Pádel'&&g.level==='Avanzado').forEach(g=>{html=html.replace(`<input type="hidden" name="id" value="${g.id}">`,`<input type="hidden" name="id" value="${g.id}">${select('Aplicar ventaja de puntos (opcional)','redemption',[['','Sin ventaja: precio indicado'],...eligible.map(r=>[r.id,'Bono de clase avanzada: 0 € demo'])])}`)});return html};
const tournamentsBeforeDiscounts=tournamentCards;
tournamentCards=function(){let html=tournamentsBeforeDiscounts();if(!admin()){let eligible=state.redemptions.filter(r=>r.status==='Reservada'&&r.reward==='tournament');if(eligible.length)state.tournaments.forEach(t=>{html=html.replace(`<input type="hidden" name="id" value="${t.id}">`,`<input type="hidden" name="id" value="${t.id}">${select('Aplicar ventaja de puntos (opcional)','redemption',[['','Sin descuento: precio indicado'],...eligible.map(r=>[r.id,'20% de descuento ficticio en torneo'])])}`)})}return html};
// Direct links are demo selectors, not real authentication or university SSO.
const attendanceBeforeGuidedDemo=crmAttendance;
crmAttendance=function(){return `<section class="card"><h2>Prueba guiada de check-in · solo datos ficticios</h2><p>Crea una reserva de prueba que empieza ahora para probar el QR sin esperar a otra hora. No es una reserva real. Se comprueba que no solape un compromiso o una pista ocupada.</p>${gameForm('demo_checkin_session',`${select('Cuenta para la prueba','user',state.users.map(u=>[u.id,u.name]))}${select('Instalación de prueba','facility',state.facilities.filter(f=>!f.blocked).map(f=>[f.id,f.name]))}<label class="check wide"><input name="reviewed" type="checkbox" required>Crear un registro ficticio para probar la demo, no una asistencia real.</label><button>Crear reserva de prueba ahora</button>`)}</section>`+attendanceBeforeGuidedDemo()};
function refreshCheckoutPreviews(){document.querySelectorAll('[data-game-form="school_checkout"],[data-game-form="tournament_join"]').forEach(f=>{let update=()=>{let price=Number(f.elements.expected_price?.value||0),redeemed=!!f.elements.redemption?.value,final=redeemed?(f.dataset.gameForm==='school_checkout'?0:Math.round(price*.8*100)/100):price,output=f.querySelector('.checkout-preview');if(output)output.textContent='Total de prueba a confirmar: '+money(final)+(redeemed?' · ventaja aplicada':'')+' · sin cobro real.'};f.addEventListener('change',update);update()})}
const tournamentCardsBeforeRoster=tournamentCards;
tournamentCards=function(){let html=tournamentCardsBeforeRoster();state.tournaments.forEach(t=>{let list=(state.tournament_public_roster||[]).filter(p=>p.tournament===t.id),roster=`<section class="card"><h3>Participantes · ${esc(t.name)}</h3><p class="muted">El alias y el avatar elegidos solo se muestran cuando el usuario activa su publicación. La equipación es cosmética y no certifica el nivel.</p><div class="participant-roster">${rows(list,p=>`<div class="participant-chip">${avatarSVG(p.avatar||{},64)}<span>${esc(p.alias)}</span></div>`,'Todavía no hay participantes inscritos.')}</div></section>`;html+=roster});return html};
const wrappedBeforeFavourite=wrappedView;
wrappedView=function(){let year=String(new Date().getFullYear()),counts={};state.reservations.filter(r=>r.user===own()&&r.status==='Asistió'&&r.date.startsWith(year)).forEach(r=>counts[r.facility]=(counts[r.facility]||0)+1);state.participation_invitations.filter(i=>i.user===own()&&i.attendance==='Asistió').forEach(i=>{let p=state.participation_sessions.find(p=>p.id===i.session&&p.date.startsWith(year));if(p)counts[p.facility]=(counts[p.facility]||0)+1});state.tournament_entries.filter(e=>e.attended_at?.startsWith(year)).forEach(e=>{let t=state.tournaments.find(t=>t.id===e.tournament);if(t?.facility)counts[t.facility]=(counts[t.facility]||0)+1});let favourite=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];return wrappedBeforeFavourite()+`<section class="card"><span class="eyebrow">TU LUGAR DEL AÑO</span><h2>${favourite?esc(facility(favourite[0])?.name):'Tu instalación favorita está por descubrir'}</h2><p>${favourite?favourite[1]+' registros de presencia validada este año.':'Aparecerá cuando tengas una asistencia validada en una instalación.'}</p></section>`};

// A dedicated entry point for messages linked to verified point redemptions.
const communicationsBeforeWinnerDesk=communicationsCRM;
function rewardMessageDraft(rewardId){const reward=state.rewards.find(r=>r.id===rewardId);if(!reward)return;communicationEditor=null;communicationDraft={id:'',title:'Tu ventaja por puntos: '+reward.name,body:`¡Tu constancia tiene recompensa!\n\nTienes un canje registrado para «${reward.name}». Este mensaje te ayudará a consultar las indicaciones de tu ventaja.\n\n[Completar lugar, fecha, horario e instrucciones antes de publicar.]\n\nEjemplo de demostración: no constituye una invitación ni un premio real.${reward.id==='talk'?' Una charla con Rafa Nadal es solo una idea; no hay ponente ni evento confirmado.':''}\n\nPuedes consultar el canje en Ventajas y tus preferencias en Buzón.`,activity:'',sport:'',level:'',campus:'',inactive_days:0,minimum_points:0,reward:reward.id,expires_at:localDateTime(7)};render();document.getElementById('campaign-composer')?.scrollIntoView?.({behavior:'smooth',block:'start'})}
communicationsCRM=function(){const section=`<section class="card winner-desk"><div><span class="eyebrow">PUNTOS → EXPERIENCIAS → COMUNIDAD</span><h2>Mensajes para quienes han conseguido una ventaja</h2><p>Elige la recompensa y prepara un anuncio dirigido a estudiantes con un canje reservado o entregado. No necesitas crear listas manualmente.</p></div><div class="winner-grid">${state.rewards.map(r=>{let ids=[...new Set(state.redemptions.filter(c=>c.reward===r.id&&['Reservada','Entregada'].includes(c.status)).map(c=>c.user))];return `<article><span class="eyebrow">${esc(r.category)}</span><h3>${esc(r.name)}</h3><p><b>${ids.length}</b> estudiantes con canje · ${r.points} puntos</p><small>${r.active?'Ventaja activa en la demo':'Propuesta pendiente de autorización'}${r.id==='talk'?' · Rafa Nadal: ejemplo, sin evento confirmado':''}</small><button class="secondary" data-winner-reward="${esc(r.id)}">Preparar mensaje →</button></article>`}).join('')}</div><p class="note">El mensaje se publica en el buzón de la app. Antes de enviarlo, guarda el borrador y revisa los destinatarios: se respetan sus preferencias de anuncios. Canjear puntos reduce el saldo, por eso esta plantilla no exige conservar un mínimo de puntos.</p></section>`;return communicationsBeforeWinnerDesk().replace(composeCampaign(),section+composeCampaign())};
const engagementBindBeforeWinnerDesk=engagementBind;
engagementBind=function(){engagementBindBeforeWinnerDesk();if(admin()&&page==='Comunicaciones')document.querySelectorAll('[data-winner-reward]').forEach(b=>b.onclick=()=>rewardMessageDraft(b.dataset.winnerReward))};

mySanctions=function(){const mine=(state.sanctions||[]).filter(p=>p.user===own()),policy=state.booking_policy||{},latest=state.reservations.filter(r=>r.user===own()&&r.status==='Asistió').sort((a,b)=>(b.validated_at||b.date).localeCompare(a.validated_at||a.date))[0];return `<section class="card attendance-desk"><span class="eyebrow">CUIDAMOS LAS PISTAS ENTRE TODOS</span><h2>Asistencia, puntos y sanciones</h2><div class="attendance-rules"><article class="attendance-good"><span class="attendance-face" aria-hidden="true">😊</span><h3>${isExternal()?"¡Muy bien! Asistencia confirmada":"¡Muy bien! Estás sumando puntos"}</h3><strong>${isExternal()?"Check-in registrado":"+12 puntos"}</strong><p>Confirma tu asistencia con el QR de la pista y la clave de tu reserva. Cada asistencia se premia una sola vez.</p></article><article class="attendance-warning"><span class="attendance-face" aria-hidden="true">😠</span><h3>Esto tendrá consecuencias…</h3><strong>${isExternal()?"Reserva liberada":"−10 puntos"}</strong><p>Si pasan 15 minutos desde el inicio sin check-in, se libera la pista y se registra la ausencia. Cancela con antelación si no puedes ir.</p></article></div><div class="note"><b>Tu límite actual: ${Number(policy.weekly_limit??state.config.weekly_limit??3)} reservas por semana.</b> ${policy.restricted?'Tienes una reducción temporal aprobada por gestión.':'No tienes una reducción temporal activa.'} El servicio puede reducir el límite en una reserva semanal durante siete días tras revisar la incidencia. No se acumulan reducciones por cada ausencia.</div>${isExternal()?'<p>Tu cuenta externa no participa en el programa de puntos.</p>':'<p>Confirma tu asistencia o cancela a tiempo para liberar la pista.</p>'}${latest?`<p class="attendance-confirmed">😊 Última asistencia confirmada: <b>${esc(facility(latest.facility)?.name||'Instalación')}</b> · ${esc(latest.date)}. ${isExternal()?'Asistencia registrada.':'Consulta los puntos asociados en «Mi progreso» y «Ventajas».'}</p>`:''}<h3>Mis incidencias y revisiones</h3>${rows(mine,p=>{const revoked=p.status==='Revocada',active=p.restriction&&!revoked&&new Date(p.until)>new Date(),r=state.reservations.find(r=>r.id===p.reservation);return `<article class="sanction-record"><div class="statusline"><h3>${revoked?'↩':'😠'} ${esc(p.reason)}</h3>${badge(p.status,revoked?'':'warn')}</div><p>${r?esc(facility(r.facility)?.name||'Instalación')+' · '+esc(r.date)+' '+esc(r.time):'Reserva vinculada a esta incidencia'}</p><p><b>${isExternal()?'Sin penalización de puntos para cuentas externas':revoked?p.penalty+' puntos devueltos': '−'+p.penalty+' puntos'}</b>${active?' · Una reserva menos por semana hasta '+esc(p.until.slice(0,10)):p.restriction?' · Periodo de restricción finalizado':''}</p>${p.resolution?`<p>Resolución: ${esc(p.resolution)}</p>`:''}${p.status==='Revisión solicitada'?'<p>Tu explicación está pendiente de respuesta. La reducción del límite queda suspendida durante la revisión.</p>':''}${!revoked&&(p.status!=='Confirmada'||!p.appeal)?gameForm('sanction_appeal',`<input type="hidden" name="id" value="${esc(p.id)}">${field('¿Hubo un problema? Explica lo ocurrido (datos ficticios)','reason','text',p.appeal||'','required maxlength="500"')}<button>Solicitar revisión</button>`):''}</article>`},'😊 No tienes incidencias. Gracias por liberar tu pista cuando no puedes asistir.')}<p class="muted">Un problema de acceso puede ocurrir. Solicita revisión si el registro no es correcto; una resolución favorable devuelve los puntos.</p></section>`};

peerView=function(){const pending=state.review_opportunities||[],feedback=state.my_level_feedback||[],declared=person(own()).sport_levels||{};return `<section class="card peer-level"><span class="eyebrow">NIVEL DECLARADO + EXPERIENCIA COMPARTIDA</span><h2>¿Jugamos al mismo nivel?</h2><p>Tu nivel lo eliges tú. Quienes han jugado contigo pueden aportar una referencia para encontrar partidas más equilibradas.</p><div class="peer-level-steps"><span>01 · Jugáis juntos</span><span>02 · Se valida la asistencia de ambos</span><span>03 · Una hora después, valoráis</span></div><p class="muted">Las partidas tienen una hora de duración: la valoración se abre dos horas después del inicio. Una reserva individual no identifica compañeros; para valorarlos deben figurar en una partida con presencia validada.</p><h3>Compañeros que puedes valorar ${pending.length?`· ${pending.length}`:''}</h3>${rows(pending,r=>{let p=player(r.user);return `<article class="peer-review-card"><div class="peer-review-person">${avatarSVG(p.avatar||{},65,'face')}<div><h3>${esc(p.alias)}</h3><p>${esc(r.name)} · ${esc(r.sport)}</p><small>Habéis compartido una partida con asistencia validada.</small></div></div>${gameForm('level_review',`<input type="hidden" name="id" value="${esc(r.match)}"><input type="hidden" name="user" value="${r.user}">${select('¿Qué nivel observaste en '+r.sport+'?','level',[['','Elige una opción'],...levels],'')}<p class="wide muted">Valora la técnica y la autonomía de juego, no si ganó o perdió. Si no tienes criterio suficiente, puedes dejarlo sin valorar.</p><button>Enviar valoración</button>`)}</article>`},'Todavía no tienes valoraciones pendientes. Aparecerán aquí al cumplirse el plazo y validarse la asistencia de ambos.')}<h3>Mi nivel y lo que perciben mis compañeros</h3><div class="peer-feedback-grid">${[...new Set([...Object.keys(declared),...feedback.map(f=>f.sport)])].map(sport=>{let f=feedback.find(f=>f.sport===sport),distribution=f?.distribution;return `<article><span class="eyebrow">${esc(sport)}</span><h3>${esc(declared[sport]||'Sin declarar')}</h3><p>Mi nivel declarado</p>${distribution?`<div class="peer-distribution">${Object.entries(distribution).map(([l,n])=>`<div><span>${esc(l)}</span><progress aria-label="${esc(l)}: ${n} valoraciones" value="${n}" max="${Math.max(1,f.reviews)}"></progress><b>${n}</b></div>`).join('')}</div><small>${f.reviewers} compañeros distintos · ${f.reviews} valoraciones</small>`:`<p class="note">${f?f.reviewers:0} compañeros han aportado su opinión. El detalle aparece a partir de tres compañeros distintos.</p>`}</article>`}).join('')||'<p>Añade un deporte y tu nivel en el perfil para empezar.</p>'}</div><p class="muted">Las opiniones son orientativas: no certifican tu nivel ni lo cambian automáticamente. Se permite una valoración por compañero y partida. No mostramos quién emitió cada opinión.</p></section>`};
const bookingBeforePeerShortcut=booking;
booking=function(){return bookingBeforePeerShortcut()+(!isExternal()?`<section class="card"><h2>Después de jugar: valora a tus compañeros</h2><p>${(state.review_opportunities||[]).length} valoraciones disponibles. Se abren una hora después de terminar una partida con asistencia validada.</p><button data-page="Perfil deportivo">Ver mi nivel y valorar compañeros →</button></section>`:'')};
